// Só libera de verdade se namespace, label e porta estão na mesma regra,
// com "ports" como irmão de "to". Comentários não contam.
const yaml = (output.match(/```ya?ml\r?\n([\s\S]*?)```/) || [, ''])[1]
  .replace(/^(\s*)-\s*(#.*)\r?\n\s+(from|to|ports)\s*:/gm, '$1- $3: $2')
  .replace(/#.*$/gm, '');
const regras = [];
for (const linha of yaml.split(/\r?\n/)) {
  const inicio = linha.match(/^(\s*)-\s*to\s*:/);
  if (inicio) regras.push({ recuo: inicio[1].length, linhas: [] });
  else if (regras.length) regras[regras.length - 1].linhas.push(linha);
}
const libera = (namespace, app, porta) => regras.some(({ recuo, linhas }) => {
  const texto = linhas.join('\n');
  return texto.includes(namespace)
    && new RegExp(`app:\\s*${app}\\b`).test(texto)
    && new RegExp(`^ {${recuo + 2}}ports:`, 'm').test(texto)
    && new RegExp(`port:\\s*${porta}\\b`).test(texto);
});
return libera('forge-prod', 'forge', 5432) && libera('cerebro-prod', 'cerebro', 9200);

const yaml = (output.match(/```ya?ml\r?\n([\s\S]*?)```/) || [, ''])[1].replace(/#.*$/gm, '');
