return yaml.split(/^---\s*$/m).some((documento) => {
  const ingress = (documento.split(/^\s*ingress:/m)[1] || '').split(/^\s*egress:/m)[0];
  return ingress.includes('relay-prod') && /app:\s*relay\b/.test(ingress);
});

// Cada item de ingress/egress precisa de "#" na própria linha ou na anterior.
