  .replace(/^(\s*)-\s*(#.*)\r?\n\s+(from|to|ports)\s*:/gm, '$1- $3: $2');
const linhas = yaml.split(/\r?\n/);
const regras = linhas
  .map((linha, i) => ({ linha, anterior: linhas[i - 1] || '' }))
  .filter(({ linha }) => /^\s*-\s*(from|to|ports)\s*:/.test(linha));
return regras.length >= 4
  && regras.every(({ linha, anterior }) => linha.includes('#') || /^\s*#/.test(anterior));

